set -e
WT="{ROOT}/.shiploop-runs/work-20261114-213147-b8da7b/worktree"
SCRATCH="{ROOT}/.shiploop-runs/work-20261114-213147-b8da7b/run/scratch"
SRC="{ROOT}/work"

# Access probe: source checkout
{
  echo "cwd=$SRC"
  echo "date=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  git -C "$SRC" status --porcelain=v1 -b
  git -C "$SRC" rev-parse HEAD
} > "$SCRATCH/access-source-git-status.txt"

# Hour math + inclusive overdue
node -e '
const created = "2025-09-01T08:00:00.000Z";
const t0 = Date.parse(created);
const hours = { urgent: 4, high: 24, normal: 72, low: 168 };
const dues = {};
for (const [p, h] of Object.entries(hours)) {
  dues[p] = new Date(t0 + h * 3600000).toISOString();
}
function overdue(nowIso, dueIso) {
  return Date.parse(nowIso) >= Date.parse(dueIso);
}
const report = {
  created,
  dues,
  now_equals_urgent_due: overdue(dues.urgent, dues.urgent),
  now_one_ms_before: overdue(new Date(Date.parse(dues.urgent) - 1).toISOString(), dues.urgent),
  now_one_ms_after: overdue(new Date(Date.parse(dues.urgent) + 1).toISOString(), dues.urgent),
};
process.stdout.write(JSON.stringify(report, null, 2) + "\n");
' > "$SCRATCH/hour-math.json"

# Fresh due-bearing fixture for CLI and load/save probes
node -e '
const fs = require("node:fs");
const path = require("node:path");
const scratch = process.argv[1];
const doc = {
  version: 1,
  savedAt: "2025-09-01T08:00:00.000Z",
  nextNumber: 3,
  extraRoot: "should-drop-on-save",
  tickets: [
    {
      id: "T-0001",
      title: "VPN drops",
      priority: "high",
      requester: "maria@example.com",
      status: "open",
      created: "2025-09-01T08:00:00.000Z",
      updated: "2025-09-01T08:00:00.000Z",
      due: "2025-09-02T08:00:00.000Z",
    },
    {
      id: "T-0002",
      title: "Printer jams",
      priority: "low",
      requester: "li@example.com",
      status: "in_progress",
      created: "2025-09-01T08:00:00.000Z",
      updated: "2025-09-01T08:00:00.000Z",
      due: "not-a-time",
    },
  ],
  audit: [],
  outbox: { nextId: 1, events: [] },
};
fs.writeFileSync(path.join(scratch, "due-bearing-v1.json"), JSON.stringify(doc, null, 2) + "\n");
' "$SCRATCH"

# 1.4.0 persistence load of due-bearing file
cd "$WT"
node -e '
const fs = require("node:fs");
const path = require("node:path");
const { createPersistence, DataFileError } = require("./src/persistence");
const scratch = process.argv[1];
const file = path.join(scratch, "due-bearing-v1.json");
const loaded = createPersistence(file).load();
const shown = loaded.tickets.map((t) => ({ id: t.id, title: t.title, status: t.status, keys: Object.keys(t), due: t.due ?? null }));
const v2file = path.join(scratch, "due-bearing-v2.json");
const v2 = JSON.parse(fs.readFileSync(file, "utf8"));
v2.version = 2;
fs.writeFileSync(v2file, JSON.stringify(v2));
let version2;
try {
  createPersistence(v2file).load();
  version2 = "loaded";
} catch (error) {
  version2 = error.name + ": " + error.message;
}
const report = { ids: loaded.tickets.map((t) => t.id), shown, version2, extraRootAfterLoad: loaded.extraRoot ?? null };
fs.writeFileSync(path.join(scratch, "rollback-load-due.json"), JSON.stringify(report, null, 2) + "\n");
' "$SCRATCH"

# CLI list / show / raw on due-bearing file (1.4.0 code, read-only)
{
  echo "=== list ==="
  DATA_FILE="$SCRATCH/due-bearing-v1.json" node "$WT/bin/tickets.js" list; echo "exit=$?"
  echo "=== list --raw ==="
  DATA_FILE="$SCRATCH/due-bearing-v1.json" node "$WT/bin/tickets.js" list --raw; echo "exit=$?"
  echo "=== show T-0001 ==="
  DATA_FILE="$SCRATCH/due-bearing-v1.json" node "$WT/bin/tickets.js" show T-0001; echo "exit=$?"
  echo "=== show T-0002 ==="
  DATA_FILE="$SCRATCH/due-bearing-v1.json" node "$WT/bin/tickets.js" show T-0002; echo "exit=$?"
} > "$SCRATCH/rollback-cli-due.txt"

# 1.4.0 save after mutation on a COPY
cp "$SCRATCH/due-bearing-v1.json" "$SCRATCH/due-bearing-v1-save-copy.json"
cd "$WT"
node -e '
const fs = require("node:fs");
const path = require("node:path");
const { createPersistence } = require("./src/persistence");
const { TicketStore } = require("./src/store");
const { manualClock } = require("./src/clock");
const scratch = process.argv[1];
const file = path.join(scratch, "due-bearing-v1-save-copy.json");
const clock = manualClock("2025-09-01T09:00:00.000Z");
const store = TicketStore.open({ clock, persistence: createPersistence(file, { clock }) });
store.update("T-0001", { title: "VPN drops still" }, "sam");
const after = JSON.parse(fs.readFileSync(file, "utf8"));
const report = {
  version: after.version,
  extraRoot: Object.prototype.hasOwnProperty.call(after, "extraRoot"),
  ticketIds: after.tickets.map((t) => t.id),
  ticketKeys: after.tickets.map((t) => Object.keys(t)),
  dues: after.tickets.map((t) => t.due ?? null),
  titles: after.tickets.map((t) => t.title),
};
fs.writeFileSync(path.join(scratch, "rollback-save-due.json"), JSON.stringify(report, null, 2) + "\n");
' "$SCRATCH"

# Confirm original due-bearing fixture still has due (CLI did not write)
node -e '
const fs = require("node:fs");
const path = require("node:path");
const scratch = process.argv[1];
const doc = JSON.parse(fs.readFileSync(path.join(scratch, "due-bearing-v1.json"), "utf8"));
process.stdout.write(JSON.stringify({
  stillHasDue: doc.tickets.map((t) => t.due ?? null),
  extraRoot: doc.extraRoot ?? null,
}, null, 2) + "\n");
' "$SCRATCH" > "$SCRATCH/due-bearing-after-cli.json"

# LOG_REQUESTS exact vs trim (current 1.4.0 loadConfig)
cd "$WT"
node -e '
const { loadConfig } = require("./src/config");
const report = {
  unset: loadConfig({}).logRequests,
  one: loadConfig({ LOG_REQUESTS: "1" }).logRequests,
  spaced: loadConfig({ LOG_REQUESTS: " 1" }).logRequests,
  on: loadConfig({ LOG_REQUESTS: "on" }).logRequests,
  trueish: loadConfig({ LOG_REQUESTS: "true" }).logRequests,
};
process.stdout.write(JSON.stringify(report, null, 2) + "\n");
' > "$SCRATCH/log-requests-flag.json"

echo DONE
ls -l "$SCRATCH"

